import pandas as pd
import numpy as np
from datetime import datetime

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    high_ts = watermark["high_ts"].iloc[0]

    # Filter events by watermark
    cdc_events = cdc_events[cdc_events["event_ts"] <= high_ts].copy()

    # Sort events by item_id, then event_ts, then event_seq for sequential application
    cdc_events = cdc_events.sort_values(["item_id", "event_ts", "event_seq"]).reset_index(drop=True)

    # Initialize snapshot as a dictionary for easier manipulation
    snapshot = {}

    # Load existing snapshot into dictionary
    for _, row in target_snapshot.iterrows():
        item_id = row["item_id"]
        snapshot[item_id] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"]
        }

    # Apply events sequentially
    for _, event in cdc_events.iterrows():
        item_id = event["item_id"]
        op = event["op"]
        qty = event["qty"]
        event_ts = event["event_ts"]

        if op == 'R':  # Receipt - add qty
            if item_id not in snapshot:
                # Item doesn't exist, start from 0
                snapshot[item_id] = {
                    "qty_on_hand": 0.0,
                    "last_event_ts": event_ts
                }
            snapshot[item_id]["qty_on_hand"] += qty
            snapshot[item_id]["last_event_ts"] = event_ts

        elif op == 'A':  # Adjustment - absolute reset
            # Note: 'A' creates/recreates the item with absolute qty
            snapshot[item_id] = {
                "qty_on_hand": qty,
                "last_event_ts": event_ts
            }

        elif op == 'D':  # Delist - remove item
            if item_id in snapshot:
                del snapshot[item_id]

    # Convert snapshot dictionary back to DataFrame
    result_rows = []
    for item_id, data in snapshot.items():
        result_rows.append({
            "item_id": item_id,
            "qty_on_hand": data["qty_on_hand"],
            "last_event_ts": data["last_event_ts"]
        })

    if result_rows:
        new_snapshot = pd.DataFrame(result_rows)
    else:
        new_snapshot = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])

    # Ensure correct dtypes
    new_snapshot = new_snapshot.astype({
        "item_id": "int64",
        "qty_on_hand": "float64",
        "last_event_ts": "datetime64[us]"
    })

    return {"new_snapshot": new_snapshot}
